using System.Buffers.Binary;
using System.IO.Compression;

namespace Meziantou.Framework.WebPlatform.Unicode;

/// <summary>
/// A word list of a Southeast Asian script (the dictionaries of ICU, see <see cref="SoutheastAsianWordBreaker"/>): a trie of the
/// words, embedded in the library (<c>Unicode/Segmentation/&lt;name&gt;.dict</c>, generated by tools/Meziantou.Framework.WebPlatform.SpecGen
/// <c>SegmentationGenerator</c>, which describes the format). It is immutable: an instance is shared by all the threads.
/// </summary>
internal sealed class WordDictionary
{
    private const string ResourcePrefix = "Meziantou.Framework.WebPlatform.Unicode.Segmentation.";
    private const byte FormatVersion = 1;

    private readonly int _codePointBase;
    private readonly byte[] _data;
    private readonly int _letters;
    private readonly int _wordEnds;

    // The index of the first child of each node (the nodes are in breadth-first order)
    private readonly int[] _firstChild;

    private WordDictionary(byte[] data)
    {
        if (data.Length < 12 || data[0] != FormatVersion)
            throw new InvalidDataException("The word list has an unsupported format");

        _codePointBase = BinaryPrimitives.ReadInt32LittleEndian(data.AsSpan(4));
        var count = BinaryPrimitives.ReadInt32LittleEndian(data.AsSpan(8));
        _data = data;
        _letters = 12 + count;
        _wordEnds = _letters + count;
        _firstChild = new int[count];
        var next = 1;
        for (var i = 0; i < count; i++)
        {
            _firstChild[i] = next;
            next += data[12 + i];
        }
    }

    /// <summary>Loads the word list of an embedded resource (e.g. <c>thai</c>).</summary>
    public static WordDictionary Load(string name)
    {
        using var stream = typeof(WordDictionary).Assembly.GetManifestResourceStream(ResourcePrefix + name + ".dict") ?? throw new InvalidOperationException($"The word list '{name}' is missing");
        var compressed = new byte[stream.Length];
        stream.ReadExactly(compressed);

        // A 32-bit length, then the Brotli stream (GeneratorContext.WriteCompressedFile of tools/Meziantou.Framework.WebPlatform.SpecGen)
        var data = new byte[BinaryPrimitives.ReadInt32LittleEndian(compressed)];
        if (!BrotliDecoder.TryDecompress(compressed.AsSpan(4), data, out var written) || written != data.Length)
            throw new InvalidDataException($"The word list '{name}' is invalid");

        return new WordDictionary(data);
    }

    /// <summary>
    /// Finds the words of the list that start the text at <paramref name="start"/> and have at most <paramref name="maxLength"/>
    /// characters, as <c>DictionaryMatcher::matches</c> of ICU: writes their lengths in increasing order (at most
    /// <c>lengths.Length</c>) and returns their number. <paramref name="prefix"/> is the number of characters that were read: the
    /// longest prefix of a word, and the character that does not continue it.
    /// </summary>
    public int Matches(ReadOnlySpan<char> text, int start, int maxLength, Span<int> lengths, out int prefix)
    {
        var data = _data.AsSpan();
        var node = 0;
        var count = 0;
        prefix = 0;
        for (var i = start; i < text.Length; i++)
        {
            // BytesDictionaryMatcher::transform: the characters of the block of the script and the joiners
            var c = text[i];
            var letter = c switch
            {
                (char)0x200C => 0xFE,
                (char)0x200D => 0xFF,
                _ => c - _codePointBase is >= 0 and <= 0xFD and var offset ? offset : -1,
            };

            prefix++;
            node = letter < 0 ? -1 : FindChild(data, node, (byte)letter);
            if (node < 0)
                break;

            if ((data[_wordEnds + (node >> 3)] & (1 << (node & 7))) != 0)
            {
                if (count < lengths.Length)
                {
                    lengths[count] = i + 1 - start;
                    count++;
                }

                // (no longer word continues it: USTRINGTRIE_FINAL_VALUE)
                if (data[12 + node] == 0)
                    break;
            }

            if (i + 1 - start >= maxLength)
                break;
        }

        return count;
    }

    private int FindChild(ReadOnlySpan<byte> data, int node, byte letter)
    {
        // The children are sorted by letter
        var low = _firstChild[node];
        var high = low + data[12 + node] - 1;
        while (low <= high)
        {
            var middle = (low + high) >>> 1;
            var value = data[_letters + middle];
            if (value == letter)
                return middle;

            if (value < letter)
            {
                low = middle + 1;
            }
            else
            {
                high = middle - 1;
            }
        }

        return -1;
    }
}
